<span class="line">    <span class="token keyword">const</span> el <span class="token operator">=</span> elementsRef<span class="token punctuation">.</span>value<span class="token punctuation">[</span>anim<span class="token punctuation">.</span>elementId<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
